function gcPoints(a,b,n=64){const out=[];for(let i=0;i<=n;i++){const t=i/n;const p1=a.lat*Math.PI/180,l1=a.lon*Math.PI/180,p2=b.lat*Math.PI/180,l2=b.lon*Math.PI/180;const A=[Math.cos(p1)*Math.cos(l1),Math.cos(p1)*Math.sin(l1),Math.sin(p1)],B=[Math.cos(p2)*Math.cos(l2),Math.cos(p2)*Math.sin(l2),Math.sin(p2)];let dot=Math.max(-1,Math.min(1,A[0]*B[0]+A[1]*B[1]+A[2]*B[2])),w=Math.acos(dot);let V;if(w<1e-9)V=A;else{const s=Math.sin(w),a1=Math.sin((1-t)*w)/s,b1=Math.sin(t*w)/s;V=[a1*A[0]+b1*B[0],a1*A[1]+b1*B[1],a1*A[2]+b1*B[2]]}out.push([Math.atan2(V[1],V[0])*180/Math.PI,Math.atan2(V[2],Math.hypot(V[0],V[1]))*180/Math.PI])}return out}
function destinationPoint(lat,lon,bearing,dist){const R=6371000,b=bearing*Math.PI/180,p1=lat*Math.PI/180,l1=lon*Math.PI/180,d=dist/R,p2=Math.asin(Math.sin(p1)*Math.cos(d)+Math.cos(p1)*Math.sin(d)*Math.cos(b)),l2=l1+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(p1),Math.cos(d)-Math.sin(p1)*Math.sin(p2));return [((l2*180/Math.PI+540)%360)-180,p2*180/Math.PI]}

function renderHeader(){if(!STATE)return;$('#companyName').textContent=(STATE.profile.logo_text||STATE.user.company_name).toUpperCase();$('#cash').textContent=money(STATE.user.cash);$('#rep').textContent=STATE.user.reputation+' ★';$('#fleetCount').textContent=STATE.aircraft.length;const h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0];$('#activeHubLabel').textContent=h?h.airport.code:'—';document.documentElement.style.setProperty('--company-primary',STATE.profile.primary_color);document.documentElement.style.setProperty('--company-accent',STATE.profile.accent_color)}

async function loadState(){try{STATE=await api('/api/state');renderHeader();renderHubSelector();renderOwnedHubs();renderFleet();renderRoutes();syncWorldRoutes();syncWorldAircraft();syncIdentity();updateCockpit()}catch(e){if(e.message.includes('connect'))location.href='/login';else toast(e.message)}}

// ---------- HUB VIEW ----------
function initHubMap(){hubMap=new maplibregl.Map({container:'hubMap',style:SAT_STYLE,center:[2.55,49.01],zoom:13,pitch:58,bearing:28,maxPitch:82});hubMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');hubMap.on('load',()=>{if(activeHubIdent)loadHub(activeHubIdent)})}
function renderHubSelector(){const sel=$('#hubSelector');if(!STATE||!sel)return;const old=activeHubIdent;sel.innerHTML=STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('');if(!activeHubIdent){activeHubIdent=(STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident}sel.value=activeHubIdent||'';if(old!==activeHubIdent&&activeHubIdent)loadHub(activeHubIdent)}
$('#hubSelector').addEventListener('change',e=>{activeHubIdent=e.target.value;loadHub(activeHubIdent)});$('#hubResetView').addEventListener('click',()=>focusHub());
$('#toggleUpgrades').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');const on=e.currentTarget.classList.contains('active');hubUpgradeMarkers.forEach(m=>m.getElement().style.display=on?'grid':'none')});
$('#toggleTraffic').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');const on=e.currentTarget.classList.contains('active');hubTrafficMarkers.forEach(m=>m.getElement().style.display=on?'grid':'none')});
function focusHub(){if(!HUBSTATE||!hubMap)return;hubMap.easeTo({center:[HUBSTATE.airport.lon,HUBSTATE.airport.lat],zoom:HUBSTATE.airport.type==='large_airport'?14:HUBSTATE.airport.type==='medium_airport'?13.5:13,pitch:62,bearing:25,duration:1300})}
async function loadHub(ident){if(!hubMap||!hubMap.loaded())return;try{HUBSTATE=await api('/api/hub/'+encodeURIComponent(ident));$('#hubTitle').textContent=`${HUBSTATE.airport.code} · ${HUBSTATE.airport.name}`;$('#hubMeta').textContent=`${HUBSTATE.airport.municipality||''} · Hub niv. ${HUBSTATE.hub.level} · ${HUBSTATE.airport.runway_count} piste(s)`;drawHubRunways();await loadHubSurfaceNetwork();drawHubUpgrades();focusHub();await refreshHubTraffic()}catch(e){toast(e.message)}}
function drawHubRunways(){if(!hubMap||!HUBSTATE)return;if(hubMap.getLayer('hub-runways'))hubMap.removeLayer('hub-runways');if(hubMap.getSource('hub-runways'))hubMap.removeSource('hub-runways');const features=HUBSTATE.airport.runways.filter(r=>r.le_lon!=null&&r.he_lon!=null).map(r=>({type:'Feature',geometry:{type:'LineString',coordinates:[[r.le_lon,r.le_lat],[r.he_lon,r.he_lat]]},properties:{name:(r.le_ident||'')+' / '+(r.he_ident||''),length:r.length_ft||0}}));hubMap.addSource('hub-runways',{type:'geojson',data:{type:'FeatureCollection',features}});hubMap.addLayer({id:'hub-runways',type:'line',source:'hub-runways',paint:{'line-color':'#6ee7ff','line-width':['interpolate',['linear'],['zoom'],11,1,16,4],'line-opacity':.72}})}
function clearMarkers(arr){arr.forEach(m=>m.remove());arr.length=0}

async function loadHubSurfaceNetwork(){
  if(!hubMap||!HUBSTATE)return;
  ['hub-aprons','hub-taxiways','hub-osm-runways','hub-gates'].forEach(id=>hubMap.getLayer(id)&&hubMap.removeLayer(id));
  if(hubMap.getSource('hub-surface'))hubMap.removeSource('hub-surface');
  hubSurfaceLines=[];hubGatePoints=[];
  try{
    const geo=await api('/api/hub/'+encodeURIComponent(activeHubIdent)+'/surface-network');hubSurfaceSource=geo.source||'surface';
    hubMap.addSource('hub-surface',{type:'geojson',data:geo});
    hubMap.addLayer({id:'hub-aprons',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'apron'],paint:{'fill-color':'#4fa3c7','fill-opacity':.10,'fill-outline-color':'#8bdcff'}});
    hubMap.addLayer({id:'hub-taxiways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'taxiway'],paint:{'line-color':'#ffd35f','line-width':['interpolate',['linear'],['zoom'],11,.7,16,2.7],'line-opacity':.68}});
    hubMap.addLayer({id:'hub-osm-runways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'runway'],paint:{'line-color':'#8eeaff','line-width':['interpolate',['linear'],['zoom'],11,1,16,4.5],'line-opacity':.75}});
    hubMap.addLayer({id:'hub-gates',type:'circle',source:'hub-surface',filter:['in',['get','kind'],['literal',['gate','parking_position']]],paint:{'circle-radius':['interpolate',['linear'],['zoom'],12,1.5,17,4.2],'circle-color':'#f4f8fb','circle-opacity':.72,'circle-stroke-color':'#0b2330','circle-stroke-width':1}});
    (geo.features||[]).forEach(f=>{const k=f.properties?.kind;if(f.geometry?.type==='LineString'&&(k==='taxiway'||k==='runway'))hubSurfaceLines.push({kind:k,coords:f.geometry.coordinates});if(f.geometry?.type==='Point'&&(k==='gate'||k==='parking_position'))hubGatePoints.push(f.geometry.coordinates)});
    $('#hubMeta').textContent+=` · réseau sol ${hubSurfaceSource.includes('OpenStreetMap')?'OSM':'pistes'}`;
  }catch(e){console.warn('Surface network unavailable',e)}
}
function pointOnLine(coords,t){if(!coords||coords.length<2)return null;const seg=(coords.length-1)*Math.max(0,Math.min(1,t)),i=Math.min(coords.length-2,Math.floor(seg)),f=seg-i,a=coords[i],b=coords[i+1];return[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f]}

function drawHubUpgrades(){clearMarkers(hubUpgradeMarkers);HUBSTATE.nodes.forEach(n=>{const el=document.createElement('button');el.className='hub-upgrade-marker '+n.state;el.textContent=n.level?String(n.level):'+';el.title=n.name;el.addEventListener('click',()=>inspectUpgrade(n));const m=new maplibregl.Marker({element:el,anchor:'center'}).setLngLat([n.lon,n.lat]).addTo(hubMap);hubUpgradeMarkers.push(m)})}
function inspectUpgrade(n){selectedUpgrade=n;const c=$('#hubInspectorContent');let prereq=n.prereq?HUBSTATE.nodes.find(x=>x.code===n.prereq):null;c.innerHTML=`<span class="inspector-tag">${n.cat.toUpperCase()}</span><h2 class="inspector-title">${n.name}</h2><p class="muted">${n.desc}</p><div class="level-box"><div><span>NIVEAU</span><strong>${n.level} / ${n.max}</strong></div><div><span>PROCHAIN INVESTISSEMENT</span><strong>${n.level>=n.max?'MAX':money(n.price)}</strong></div></div>${!n.available&&prereq?`<div class="prereq">Prérequis : ${prereq.name} niveau 1</div>`:''}<div class="stat-row"><span>État</span><b>${n.state==='active'?'Actif':n.state==='available'?'Disponible':'Verrouillé'}</b></div><button class="primary" id="buyUpgrade" ${n.level>=n.max||!n.available?'disabled':''}>${n.level>=n.max?'Niveau maximum':n.level?'Améliorer':'Construire / débloquer'}</button>`;$('#hubInspector').classList.add('open');$('#buyUpgrade')?.addEventListener('click',async()=>{try{await api('/api/hub/upgrade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ident:activeHubIdent,code:n.code})});toast(`${n.name} amélioré`);await loadState();await loadHub(activeHubIdent)}catch(e){toast(e.message)}})}
function inspectGroundPlane(p){$('#hubInspectorContent').innerHTML=`<span class="inspector-tag">TON AVION</span><h2 class="inspector-title">${p.tail}</h2><div class="owned-plane-card"><div class="tail">${p.type}</div><small>${p.status}</small></div><button class="primary" id="watchGroundPlane">Vue cockpit / observation</button>`;$('#hubInspector').classList.add('open');$('#watchGroundPlane').addEventListener('click',()=>openCockpit(p.aircraft_id))}
async function refreshHubTraffic(){
  if(!HUBSTATE||!hubMap)return;
  clearMarkers(hubTrafficMarkers);
  const a=HUBSTATE.airport,own=HUBSTATE.own_ground_aircraft||[];

  // Player aircraft are simulation entities, but their ground movement follows the real airport network.
  own.forEach((p,i)=>{
    const gate=hubGatePoints.length?hubGatePoints[i%hubGatePoints.length].coords:[a.lon,a.lat];
    const el=document.createElement('button');el.className='aircraft-marker player-aircraft-marker';
    el.innerHTML='<span class="plane-glyph">✈</span><small>'+String(p.tail||'SKYLINE')+'</small>';
    el.addEventListener('click',()=>inspectGroundPlane(p));
    const marker=new maplibregl.Marker({element:el}).setLngLat(gate).addTo(hubMap);hubTrafficMarkers.push(marker);
    if((p.phase||'').includes('taxi'))animateAlongNetwork(marker,1000+i,'plane',16);
    if(p.ground_service&&p.ground_service!=='taxi'){
      const icons={fuel:'⛽',cleaning:'🧹',catering:'▰',passenger:'🚌',pushback:'↔'},ve=document.createElement('div');
      ve.className='ground-service-marker';ve.textContent=icons[p.ground_service]||'▰';
      const vm=new maplibregl.Marker({element:ve}).setLngLat(groundPath('vehicle',i)?.coords?.[0]||gate).addTo(hubMap);hubTrafficMarkers.push(vm);animateAlongNetwork(vm,2000+i,'vehicle',12)
    }
  });

  let live={states:[],source:'unavailable'};
  try{live=await api('/api/live-traffic?ident='+encodeURIComponent(activeHubIdent))}catch(e){console.warn('Live hub traffic unavailable',e)}
  const states=(live.states||[]).filter(x=>Number.isFinite(Number(x.lon))&&Number.isFinite(Number(x.lat)));
  const ground=states.filter(x=>x.on_ground).slice(0,36);
  const terminal=states.filter(x=>!x.on_ground&&(x.phase==='terminal-area'||Number(x.distance_km||999)<18)&&Number(x.altitude_ft||0)<9000).slice(0,16);

  const addRealMarker=(st,isGround)=>{
    const el=document.createElement('button');el.className='real-aircraft-marker '+(isGround?'surface':'terminal');
    const cs=(st.callsign||st.flight||st.reg||'LIVE').trim();
    el.innerHTML=`<span class="plane-glyph" style="transform:rotate(${Number(st.heading||0)}deg)">✈</span><small>${cs.slice(0,9)}</small>`;
    el.title=`${cs} · ${st.type||'Appareil'} · ${live.source}`;
    el.addEventListener('click',()=>{
      $('#hubInspectorContent').innerHTML=`<span class="inspector-tag">${live.source}</span><h2 class="inspector-title">${cs}</h2><div class="stat-row"><span>Appareil</span><b>${st.type||'—'} ${st.reg||''}</b></div><div class="stat-row"><span>Route</span><b>${st.origin||'—'} → ${st.destination||'—'}</b></div><div class="stat-row"><span>Position</span><b>${isGround?'Au sol / aire aéroportuaire':'Zone terminale'}</b></div><div class="stat-row"><span>Vitesse</span><b>${Math.round(Number(st.velocity_kts||0))} kt</b></div><div class="stat-row"><span>Altitude</span><b>${Math.round(Number(st.altitude_ft||0))} ft</b></div>`;
      $('#hubInspector').classList.add('open')
    });
    hubTrafficMarkers.push(new maplibregl.Marker({element:el}).setLngLat([Number(st.lon),Number(st.lat)]).addTo(hubMap))
  };
  ground.forEach(x=>addRealMarker(x,true));terminal.forEach(x=>addRealMarker(x,false));

  const meta=document.getElementById('hubMeta');
  if(meta){
    const provider=live.source||'indisponible';
    const suffix=` · trafic ${provider}: ${ground.length} au sol, ${terminal.length} proche(s)`;
    if(!meta.textContent.includes(' · trafic '))meta.textContent+=suffix;
    else meta.textContent=meta.textContent.replace(/ · trafic .*$/,'')+suffix;
  }
  // Intentionally no decorative/fake AI aircraft in ultra-realism mode.
}

// Real traffic in the current globe viewport, with FR24 official API support on the backend when licensed.
async function refreshWorldRealTraffic(){if(!worldMap||!worldMap.loaded()||worldMap.getZoom()<2.15)return;const now=Date.now();if(now-lastWorldTrafficAt<30000)return;lastWorldTrafficAt=now;const b=worldMap.getBounds();try{const d=await api(`/api/live-traffic/box?lamin=${b.getSouth()}&lomin=${b.getWest()}&lamax=${b.getNorth()}&lomax=${b.getEast()}&limit=140`);worldRealMarkers.forEach(m=>m.remove());worldRealMarkers=[];(d.states||[]).filter(x=>!x.on_ground).slice(0,140).forEach(x=>{const el=document.createElement('button');el.className='world-real-marker';el.textContent='✈';el.style.transform=`rotate(${x.heading||0}deg)`;el.title=`${x.callsign||x.flight||'Vol'} · ${x.type||''} · ${d.source}`;el.addEventListener('click',()=>{$('#worldInspectorContent').innerHTML=`<span class="inspector-tag">${d.source}</span><h2 class="inspector-title">${x.callsign||x.flight||'Vol réel'}</h2><div class="stat-row"><span>Appareil</span><b>${x.type||'—'} ${x.reg||''}</b></div><div class="stat-row"><span>Route</span><b>${x.origin||'—'} → ${x.destination||'—'}</b></div><div class="stat-row"><span>Altitude</span><b>${fmt(x.altitude_ft||0)} ft</b></div><div class="stat-row"><span>Vitesse</span><b>${Math.round(x.velocity_kts||0)} kt</b></div>`;$('#worldInspector').classList.add('open')});worldRealMarkers.push(new maplibregl.Marker({element:el}).setLngLat([x.lon,x.lat]).addTo(worldMap))})}catch(e){console.warn(e)}}
function subsolarVector(){const now=new Date(),doy=Math.floor((now-Date.UTC(now.getUTCFullYear(),0,0))/86400000),decl=23.44*Math.sin((2*Math.PI/365)*(doy-81))*Math.PI/180,utc=now.getUTCHours()+now.getUTCMinutes()/60,lon=(12-utc)*15*Math.PI/180;return[Math.cos(decl)*Math.cos(lon),Math.cos(decl)*Math.sin(lon),Math.sin(decl)]}
function nightGrid(){const s=subsolarVector(),features=[];for(let lat=-80;lat<80;lat+=10)for(let lon=-180;lon<180;lon+=10){const p=(lat+5)*Math.PI/180,l=(lon+5)*Math.PI/180,v=[Math.cos(p)*Math.cos(l),Math.cos(p)*Math.sin(l),Math.sin(p)];if(v[0]*s[0]+v[1]*s[1]+v[2]*s[2]<0)features.push({type:'Feature',geometry:{type:'Polygon',coordinates:[[[lon,lat],[lon+10,lat],[lon+10,lat+10],[lon,lat+10],[lon,lat]]]},properties:{}})}return{type:'FeatureCollection',features}}
function ensureNightLayer(){if(!worldMap||!worldMap.loaded())return;const data=nightGrid();if(worldMap.getSource('night-side'))worldMap.getSource('night-side').setData(data);else{worldMap.addSource('night-side',{type:'geojson',data});worldMap.addLayer({id:'night-side',type:'fill',source:'night-side',paint:{'fill-color':'#020711','fill-opacity':.54}})}}
function initWorldMap(){worldMap=new maplibregl.Map({container:'worldMap',style:{...SAT_STYLE,projection:{type:'globe'}},center:[10,25],zoom:1.35,pitch:18,bearing:0,maxPitch:80});worldMap.addControl(new maplibregl.NavigationControl({visualizePitch:true}),'top-right');worldMap.on('load',async()=>{worldMap.setProjection({type:'globe'});await loadMajorAirports();await addWeather();ensureNightLayer();syncWorldRoutes();syncWorldAircraft();refreshWorldRealTraffic()});worldMap.on('moveend',refreshWorldRealTraffic);worldMap.on('zoomend',refreshWorldRealTraffic);worldMap.on('click','major-airports',e=>inspectWorldAirport(e.features[0].properties));worldMap.on('click','owned-hubs',e=>inspectWorldAirport(e.features[0].properties));setInterval(()=>{ensureNightLayer();refreshWorldRealTraffic()},45000)}

// Stable observation cockpit: sky + horizon + forward satellite landscape + live weather.
function ensureCockpitMap(){if(cockpitMap)return;cockpitMap=new maplibregl.Map({container:'cockpitMap',style:SAT_STYLE,center:[2.5,49],zoom:9,pitch:84,bearing:0,interactive:false,attributionControl:true,maxPitch:85})}
function localLight(lon){const d=new Date(),h=(d.getUTCHours()+d.getUTCMinutes()/60+lon/15+24)%24;if(h<5.5||h>20.5)return'night';if(h<7||h>19)return'dawn';return'day'}
let lastCockpitWeather={cloud:20,prec:0,code:0};
window.openCockpit=id=>{selectedAircraft=id;ensureCockpitMap();$('#cockpitModal').classList.add('open');setTimeout(()=>cockpitMap?.resize(),80);updateCockpit(true)};
async function updateCockpit(force=false){if(!selectedAircraft||!STATE)return;const a=STATE.aircraft.find(x=>x.id===selectedAircraft);if(!a)return;const f=a.flight;$('#cpAircraft').textContent=`${a.tail} · ${a.spec.name}`;if(!f){$('#cpFlight').textContent='AU SOL';$('#cpStatus').textContent='Disponible';return}$('#cpFlight').textContent=`${f.from} → ${f.to}`;$('#cpAlt').textContent=fmt(f.altitude_ft)+' ft';$('#cpSpeed').textContent=f.speed_kts+' kt';$('#cpHeading').textContent=Math.round(f.heading)+'°';$('#cpFuel').textContent=f.fuel_percent+'%';$('#cpStatus').textContent=f.status;const light=localLight(f.lon),sky=$('#cockpitSky');sky.classList.toggle('night',light==='night');$('#cockpitModal').classList.toggle('night',light==='night');if(light==='dawn'&&!sky.classList.contains('night'))sky.style.background='linear-gradient(#173552,#d97b68 66%,#f2c28f 100%)';else sky.style.background='';if(cockpitMap&&cockpitMap.loaded()){const z=f.airborne?Math.max(7.1,10.7-f.altitude_ft/13000):15.5;cockpitMap.easeTo({center:[f.lon,f.lat],bearing:f.heading,pitch:f.airborne?84:67,zoom:z,duration:force?0:2600,easing:t=>t})}const now=Date.now();if(force||now-lastWeatherAt>90000){lastWeatherAt=now;try{const w=await api(`/api/weather/current?lat=${f.lat}&lon=${f.lon}`),c=w.current||{};lastCockpitWeather={cloud:Number(c.cloud_cover||0),prec:Number(c.precipitation||0),code:Number(c.weather_code||0)};$('#cpWeather').textContent=w.ok?`${Math.round(lastCockpitWeather.cloud)}% nuages · ${Math.round(c.wind_speed_10m||0)} kt`:'Indispo'}catch{}}const {cloud,prec,code}=lastCockpitWeather;$('#cockpitClouds').style.opacity=Math.min(.9,.04+cloud/112);$('#rainStreaks').style.opacity=prec>.15?Math.min(.7,.15+prec/6):0;$('#cockpitHaze').style.opacity=.18+cloud/180;stormy=code>=95||prec>=3;if(stormy&&Math.random()>.78)triggerStorm()}

// Company management views.
$$('[data-mtab]').forEach(b=>b.addEventListener('click',()=>{managementTab=b.dataset.mtab;$$('[data-mtab]').forEach(x=>x.classList.toggle('active',x===b));renderManagement()}));
document.querySelector('[data-nav="management"]')?.addEventListener('click',()=>setTimeout(renderManagement,0));
async function renderManagement(){const root=$('#managementContent');if(!root)return;root.innerHTML='<div class="empty-state"><b>Chargement…</b></div>';try{if(managementTab==='staff')return renderStaff(root);if(managementTab==='marketing')return renderMarketing(root);if(managementTab==='finance')return renderFinance(root);if(managementTab==='partners')return renderPartners(root);if(managementTab==='hotels')return renderHotels(root)}catch(e){root.innerHTML=`<div class="empty-state"><b>Erreur</b><span>${e.message}</span></div>`}}
async function renderStaff(root){const [staff,cands]=await Promise.all([api('/api/staff'),api('/api/staff/candidates')]);root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Équipe (${staff.items.length})</h2><p class="muted">Pilotes, PNC, maintenance, sol et fonctions siège. Si tes pools sont insuffisants, OPS fait appel à du personnel contractuel plus coûteux.</p><div>${staff.items.length?staff.items.map(e=>`<div class="staff-card"><div><b>${e.name}</b><span>${e.role_label}${e.qualification?' · '+e.qualification:''} · ${money(e.salary_monthly)}/mois · qualité ${e.quality}%</span></div><button class="mini-btn danger-btn" data-fire="${e.id}">Licencier</button></div>`).join(''):'<div class="empty-state"><span>Aucun salarié recruté.</span></div>'}</div></section><section class="panel"><h2>Marché du recrutement</h2><div id="candidateList">${cands.items.slice(0,24).map(c=>`<div class="staff-card"><div><b>${c.name}</b><span>${c.role_label}${c.qualification?' · '+c.qualification:''} · ${money(c.salary_monthly)}/mois · qualité ${c.quality}%</span></div><button class="mini-btn" data-hire="${c.id}">Recruter · ${money(c.hiring_fee)}</button></div>`).join('')}</div></section></div>`;root.querySelectorAll('[data-fire]').forEach(b=>b.addEventListener('click',async()=>{await api('/api/staff/'+b.dataset.fire,{method:'DELETE'});toast('Employé libéré');renderStaff(root);loadState()}));root.querySelectorAll('[data-hire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/hire',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_id:b.dataset.hire,home_hub:activeHubIdent||''})});toast('Recrutement effectué');await loadState();renderStaff(root)}catch(e){toast(e.message)}}))}
async function renderMarketing(root){const d=await api('/api/marketing');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Campagnes</h2><div class="estimate-grid"><div><small>Boost demande</small><b>+${Math.round(d.boost*100)}%</b></div><div><small>Directeur marketing</small><b>${d.has_director?'Oui':'Non'}</b></div></div>${d.campaigns.map(c=>`<div class="list-row"><div><b>${c.name}</b><small>${money(c.spend)} · ${c.active?'ACTIVE':'Terminée'}</small></div><b>+${Math.round(c.impact*100)}%</b></div>`).join('')||'<div class="empty-state"><span>Aucune campagne.</span></div>'}</section><section class="panel"><h2>Lancer une campagne</h2><label>Type<select id="mtype"><option value="brand">Notoriété mondiale</option><option value="digital">Acquisition digitale</option><option value="route">Lancement de ligne</option><option value="premium">Premium</option><option value="loyalty">Fidélité</option></select></label><label>Budget (€)<input type="number" id="mspend" value="1000000" min="100000"></label><label>Durée<input type="number" id="mdays" value="14" min="3" max="60"></label><button class="primary" id="startCampaign">Lancer</button></section></div>`;$('#startCampaign').addEventListener('click',async()=>{try{await api('/api/marketing',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({campaign_type:$('#mtype').value,spend:Number($('#mspend').value),duration_days:Number($('#mdays').value)})});toast('Campagne lancée');await loadState();renderMarketing(root)}catch(e){toast(e.message)}})}
async function renderFinance(root){const d=await api('/api/finance');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Finance</h2><div class="estimate-grid"><div><small>Trésorerie</small><b>${money(d.cash)}</b></div><div><small>Masse salariale</small><b>${money(d.monthly_payroll)}/mois</b></div><div><small>Dette</small><b>${money(d.loans.reduce((s,x)=>s+x.outstanding,0))}</b></div><div><small>Dernier vol</small><b>${d.flights[0]?money(d.flights[0].profit):'—'}</b></div></div><h3>Résultat par vol</h3><div class="table-scroll"><table class="finance-table"><thead><tr><th>Vol</th><th>Pax</th><th>Recettes</th><th>Coûts</th><th>Profit</th></tr></thead><tbody>${d.flights.slice(0,30).map(f=>`<tr><td>${f.tail} · ${f.origin}→${f.destination}</td><td>${f.passengers} · ${Math.round(f.load_factor*100)}%</td><td>${money(f.ticket_revenue+f.ancillary_revenue)}</td><td>${money(f.operating_cost)}</td><td class="${f.profit>=0?'profit-pos':'profit-neg'}">${money(f.profit)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Banque</h2><label>Montant<input id="loanAmount" type="number" value="25000000" min="1000000"></label><label>Durée<select id="loanTerm"><option>12</option><option>24</option><option selected>36</option><option>48</option><option>60</option></select></label><button class="primary" id="takeLoan">Demander l’emprunt</button><h3>Emprunts en cours</h3>${d.loans.map(l=>`<div class="manage-card"><b>${money(l.outstanding)}</b><p>${(l.apr*100).toFixed(2)}% · ${l.term_months} mois</p><button class="mini-btn" data-repay="${l.id}" data-out="${l.outstanding}">Rembourser 10%</button></div>`).join('')||'<p class="muted">Aucun emprunt.</p>'}</section></div>`;$('#takeLoan').addEventListener('click',async()=>{try{await api('/api/finance/loan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#loanAmount').value),term_months:Number($('#loanTerm').value)})});toast('Emprunt débloqué');await loadState();renderFinance(root)}catch(e){toast(e.message)}});root.querySelectorAll('[data-repay]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/finance/loan/repay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan_id:Number(b.dataset.repay),amount:Number(b.dataset.out)*.1})});toast('Remboursement effectué');await loadState();renderFinance(root)}catch(e){toast(e.message)}}))}
async function renderPartners(root){const d=await api('/api/partners');root.innerHTML=`<div class="management-grid three">${d.offers.map(o=>`<article class="manage-card"><h3>${o.name}</h3><small>${o.type}</small><p>Bonus revenus +${(o.revenue_bonus*100).toFixed(1)}% · réputation +${o.reputation_bonus}</p><button class="${o.owned?'secondary':'primary'}" data-partner="${o.id}" ${o.owned?'disabled':''}>${o.owned?'Partenaire actif':'Signer · '+money(o.fee)}</button></article>`).join('')}</div>`;root.querySelectorAll('[data-partner]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/partners',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer_id:b.dataset.partner})});toast('Partenariat signé');await loadState();renderPartners(root)}catch(e){toast(e.message)}}))}
async function renderHotels(root){const d=await api('/api/hotels');root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Mes hôtels</h2>${d.items.map(h=>`<div class="manage-card"><h3>${h.name}</h3><p>${h.airport_ident} · ${h.stars}★ · ${h.rooms} chambres · niv. ${h.level}/10</p><button class="mini-btn" data-hotelup="${h.id}">Agrandir</button></div>`).join('')||'<p class="muted">Aucun hôtel construit.</p>'}</section><section class="panel"><h2>Construire un hôtel</h2><label>Hub<select id="hotelHub">${STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('')}</select></label><label>Nom<input id="hotelName" value="${STATE.profile.logo_text} Hotel"></label><label>Étoiles<select id="hotelStars"><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Chambres<input id="hotelRooms" type="number" value="120" min="60" max="900"></label><button class="primary" id="buildHotel">Construire</button></section></div>`;$('#buildHotel').addEventListener('click',async()=>{try{await api('/api/hotels',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({airport_ident:$('#hotelHub').value,name:$('#hotelName').value,stars:Number($('#hotelStars').value),rooms:Number($('#hotelRooms').value)})});toast('Hôtel construit');await loadState();renderHotels(root)}catch(e){toast(e.message)}});root.querySelectorAll('[data-hotelup]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/hotels/upgrade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hotel_id:Number(b.dataset.hotelup)})});toast('Hôtel agrandi');await loadState();renderHotels(root)}catch(e){toast(e.message)}}))}

function loadState(){return api('/api/state').then(d=>{STATE=d;renderHeader();renderHubSelector();renderOwnedHubs();renderFleet();renderRoutes();syncWorldRoutes();syncWorldAircraft();syncIdentity();updateCockpit();if(document.querySelector('[data-view="management"]')?.classList.contains('active'))renderManagement()}).catch(e=>{if(e.message.includes('connect'))location.href='/login';else toast(e.message)})}

function initWorldAITraffic(){ aiWorldMarkers.forEach(m=>m.remove()); aiWorldMarkers=[]; aiWorldFlights=[]; }


// ---------- v0.6 PREMIUM REALISM OVERRIDES ----------
function nav(name){
  $$('.view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));
  $$('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===name));
  $('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open');
  if(name==='hub'){
    if(!hubMap)initHubMap();
    setTimeout(()=>{hubMap?.resize();if(activeHubIdent&&hubMap?.loaded())loadHub(activeHubIdent)},80);
  }
  if(name==='world'){
    if(!worldMap)initWorldMap();
    setTimeout(()=>{worldMap?.resize();syncWorldRoutes();syncWorldAircraft()},80);
  }
  if(name==='management')setTimeout(renderManagement,0);
  window.scrollTo(0,0);
}

function renderHeader(){
  if(!STATE)return;
  $('#companyName').textContent=(STATE.profile.logo_text||STATE.user.company_name).toUpperCase();
  $('#cash').textContent=money(STATE.user.cash);$('#rep').textContent=STATE.user.reputation+'%';$('#fleetCount').textContent=STATE.aircraft.length;
  $('#playerLevel').textContent=STATE.progression?.level||1;$('#globalSat').textContent=(STATE.company?.satisfaction||0)+'%';
  const h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0];$('#activeHubLabel').textContent=h?h.airport.code:'—';
  document.documentElement.style.setProperty('--company-primary',STATE.profile.primary_color);document.documentElement.style.setProperty('--company-accent',STATE.profile.accent_color);
}

function satClass(v){return v>=85?'good':v>=70?'warn':'bad'}
function renderHome(){
  if(!STATE)return;
  const pr=STATE.progression||{},h=STATE.hubs.find(x=>x.is_primary)||STATE.hubs[0],company=STATE.company||{};
  $('#homeUsername').textContent=STATE.user.username||'Commandant';$('#homeLevel').textContent=pr.level||1;$('#homeEraLabel').textContent=pr.era||'Fondateur';
  $('#homeEra').textContent=`${pr.era||'Fondateur'} · ${STATE.routes.length} ligne(s), ${STATE.hubs.length} hub(s). Les équipages sont affectés automatiquement selon les qualifications et le repos.`;
  $('#homeXp').textContent=`${fmt(pr.xp_current||0)} / ${fmt(pr.xp_next||0)} XP`;$('#homeXpBar').style.width=(pr.progress_pct||0)+'%';
  $('#homeProfit').textContent=money(company.today_profit||0);$('#homeFlights').textContent=`${company.today_flights||0} rotation(s)`;$('#homePax').textContent=fmt(company.today_passengers||0);
  $('#homeSat').textContent=(company.satisfaction||0)+'%';$('#homeSatLabel').textContent=(company.satisfaction||0)>=90?'Excellent':(company.satisfaction||0)>=80?'Très bon':'À développer';$('#homeFleet').textContent=STATE.aircraft.length;
  if(h){
    const sat=h.satisfaction||{score:0,label:'—'},r=h.reality||{};$('#homeHubTitle').textContent=`${h.airport.code} · ${h.airport.name}`;
    $('#homeHubBody').innerHTML=`<div class="hub-summary-photo"><div class="hub-code">${h.airport.code}</div></div><div class="hub-summary-data"><div><small>PROFIL</small><b>${r.character||'Aéroport'}</b></div><div><small>NIVEAU HUB</small><b>${h.level}</b></div><div class="sat-bar"><small>SATISFACTION</small><b>${sat.score}% · ${sat.label}</b><div class="sat-meter"><i style="width:${sat.score}%"></i></div></div><div><small>INFRASTRUCTURES ACQUISES</small><b>${h.asset_count}</b></div><div><small>ACCÈS</small><b>${(r.access||[]).slice(0,2).join(' · ')||'—'}</b></div></div>`;
  }
  const qs=STATE.quests?.items||[];$('#homeQuests').innerHTML=qs.map(q=>{const pct=Math.min(100,q.value/q.target*100);return `<div class="quest-item"><div><b>${q.label}</b><small>${fmt(q.value)} / ${fmt(q.target)} · ${money(q.cash_reward)} + ${q.xp_reward} XP</small><div class="quest-progress"><i style="width:${pct}%"></i></div></div><button data-claimquest="${q.code}" ${!q.complete||q.claimed?'disabled':''}>${q.claimed?'Récupéré':q.complete?'Récupérer':'En cours'}</button></div>`}).join('')||'<div class="empty-state"><span>Aucun objectif aujourd’hui.</span></div>';
  $('#homeQuests').querySelectorAll('[data-claimquest]').forEach(b=>b.addEventListener('click',async()=>{try{const d=await api('/api/quests/claim',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({quest_code:b.dataset.claimquest})});toast(`Récompense : ${money(d.cash_reward)} + ${d.xp_reward} XP`);await loadState()}catch(e){toast(e.message)}}));
  const crewRoutes=STATE.routes.slice(0,5);$('#homeCrew').innerHTML=crewRoutes.length?crewRoutes.map(r=>{const c=r.crew||{},cls=(c.coverage_percent||0)>=100?'risk-good':(c.coverage_percent||0)>=60?'risk-warn':'risk-bad';return `<div class="crew-route"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${c.reinforced?'Équipage renforcé long-courrier':'Équipage standard'} · affectation automatique</small></div><div class="${cls}"><b>${c.coverage_percent||0}%</b><small>${c.fatigue_risk||'—'}</small></div></div>`}).join(''):'<div class="empty-state"><span>Ouvre une ligne pour calculer la couverture équipage.</span></div>';
  const live=STATE.routes.filter(r=>r.flight).slice(0,5);$('#homeFlightsList').innerHTML=live.length?live.map(r=>`<div class="home-flight"><div><b>${r.tail} · ${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${r.flight.status}</small></div><button class="mini-btn" onclick="openCockpit(${r.aircraft_id})">Observer</button></div>`).join(''):'<div class="empty-state"><span>Aucun vol actif.</span></div>';
}

async function loadHub(ident){
  if(!hubMap||!hubMap.loaded())return;
  try{
    HUBSTATE=await api('/api/hub/'+encodeURIComponent(ident));
    $('#hubTitle').textContent=`${HUBSTATE.airport.code} · ${HUBSTATE.airport.name}`;
    $('#hubMeta').textContent=`${HUBSTATE.airport.municipality||''} · Hub niv. ${HUBSTATE.hub.level} · ${HUBSTATE.airport.runway_count} piste(s)`;
    $('#hubSatMini').textContent=(HUBSTATE.hub.satisfaction?.score||0)+'%';$('#hubRealityMini').textContent=HUBSTATE.reality?.character||'Aéroport';
    drawHubRunways();await loadHubSurfaceNetwork();drawHubUpgrades();focusHub();await refreshHubTraffic();
  }catch(e){toast(e.message)}
}

function catIcon(cat){return {'Airside':'✈','Terminal':'▤','Sécurité':'◈','Commercial':'▣','Premium':'◇','Technique':'⚙','Cargo':'□','Infrastructure':'⌂'}[cat]||'•'}
function drawHubUpgrades(){
  clearMarkers(hubUpgradeMarkers);if(!HUBSTATE)return;const visible=$('#toggleUpgrades')?.classList.contains('active');
  HUBSTATE.nodes.forEach(n=>{const el=document.createElement('button');el.className='hub-upgrade-marker '+n.state;el.textContent=`${catIcon(n.cat)} ${n.state==='locked'?'🔒':n.level||'+'}`;el.title=`${n.name} · ${n.state==='active'?'niveau '+n.level:n.state==='available'?'disponible':'verrouillé'}`;el.style.display=visible?'flex':'none';el.addEventListener('click',()=>inspectUpgrade(n));hubUpgradeMarkers.push(new maplibregl.Marker({element:el}).setLngLat([n.lon,n.lat]).addTo(hubMap))});
}

async function loadHubSurfaceNetwork(){
  if(!hubMap||!HUBSTATE)return;
  ['hub-terminals','hub-aprons','hub-taxiways','hub-osm-runways','hub-gates'].forEach(id=>hubMap.getLayer(id)&&hubMap.removeLayer(id));if(hubMap.getSource('hub-surface'))hubMap.removeSource('hub-surface');
  hubSurfaceLines=[];hubGatePoints=[];hubSurfaceFeatures=[];clearMarkers(hubAssetMarkers);
  try{
    const geo=await api('/api/hub/'+encodeURIComponent(activeHubIdent)+'/surface-network');hubSurfaceSource=geo.source||'surface';hubSurfaceFeatures=geo.features||[];hubMap.addSource('hub-surface',{type:'geojson',data:geo});
    hubMap.addLayer({id:'hub-terminals',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'terminal'],paint:{'fill-color':'#e7edf1','fill-opacity':.50,'fill-outline-color':'#ffffff'}});
    hubMap.addLayer({id:'hub-aprons',type:'fill',source:'hub-surface',filter:['==',['get','kind'],'apron'],paint:{'fill-color':'#bdd0dc','fill-opacity':.12,'fill-outline-color':'#dfeaf0'}});
    hubMap.addLayer({id:'hub-taxiways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'taxiway'],paint:{'line-color':'#e4b84f','line-width':['interpolate',['linear'],['zoom'],11,.6,17,2.7],'line-opacity':.68}});
    hubMap.addLayer({id:'hub-osm-runways',type:'line',source:'hub-surface',filter:['==',['get','kind'],'runway'],paint:{'line-color':'#f5f7f8','line-width':['interpolate',['linear'],['zoom'],11,1,17,5],'line-opacity':.72}});
    hubMap.addLayer({id:'hub-gates',type:'circle',source:'hub-surface',filter:['in',['get','kind'],['literal',['gate','parking_position']]],paint:{'circle-radius':['interpolate',['linear'],['zoom'],12,1.2,17,3.2],'circle-color':'#ffffff','circle-opacity':.58,'circle-stroke-color':'#526777','circle-stroke-width':.7}});
    hubSurfaceFeatures.forEach(f=>{const k=f.properties?.kind;if(f.geometry?.type==='LineString'&&(k==='taxiway'||k==='runway'))hubSurfaceLines.push({kind:k,coords:f.geometry.coordinates,feature:f});if(f.geometry?.type==='Point'&&(k==='gate'||k==='parking_position'))hubGatePoints.push({coords:f.geometry.coordinates,feature:f})});drawHubAssets();
    $('#hubMeta').textContent+=` · réseau sol ${hubSurfaceSource.includes('OpenStreetMap')?'OSM réel':'pistes connues'}`;
  }catch(e){console.warn(e)}
}

function drawHubAssets(){
  clearMarkers(hubAssetMarkers);if(!HUBSTATE)return;const candidates=[];const lim=HUBSTATE.airport.type==='large_airport'?120:HUBSTATE.airport.type==='medium_airport'?80:45;hubGatePoints.slice(0,lim).forEach(x=>candidates.push(x.feature));hubSurfaceFeatures.filter(f=>f.properties?.kind==='runway'&&f.geometry?.type==='LineString').forEach(f=>candidates.push(f));
  candidates.forEach((f,i)=>{const kind=f.properties?.kind,key=f.properties?.asset_key||`${kind}:${i}`,name=f.properties?.name||(`${kind==='gate'?'Porte':kind==='parking_position'?'Parking avion':'Piste'} ${i+1}`);let pt=f.geometry.type==='Point'?f.geometry.coordinates:pointOnLine(f.geometry.coordinates,.5);if(!pt)return;const owned=assetOwned(key),el=document.createElement('button');el.className=`hub-asset-marker ${owned?'owned':'locked'} ${kind==='runway'?'runway':''}`;el.textContent=owned?'✓':(kind==='gate'?'G':kind==='parking_position'?'P':'RWY');el.title=`${owned?'Acquis':'Verrouillé'} · ${name}`;el.addEventListener('click',()=>inspectHubAsset({key,kind,name,pt,owned}));hubAssetMarkers.push(new maplibregl.Marker({element:el}).setLngLat(pt).addTo(hubMap))});
}

async function renderStaff(root){
  const [staff,cands]=await Promise.all([api('/api/staff'),api('/api/staff/candidates')]);
  const crewLines=(STATE.routes||[]).map(r=>{const c=r.crew||{};return `<div class="crew-route"><div><b>${r.origin_airport.code} → ${r.partner?r.partner.to:r.destination_airport.code}</b><small>${c.qualification||'Qualification'} · ${c.reinforced?'4 pilotes en service (long-courrier)':'2 pilotes en service'} · OPS automatique</small></div><div class="${(c.coverage_percent||0)>=100?'risk-good':(c.coverage_percent||0)>=60?'risk-warn':'risk-bad'}"><b>${c.coverage_percent||0}%</b><small>${c.pilots_available||0}/${c.pilots_recommended||0} pilotes recommandés</small></div></div>`}).join('');
  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Équipages automatisés</h2><p class="muted">Tu recrutes les pilotes et PNC. OPS les affecte ensuite automatiquement aux rotations, gère les renforts long-courriers et mesure le risque fatigue. Avec 2 pilotes pour un avion la couverture est fragile ; avec 4 pilotes sur un appareil court/moyen-courrier, les rotations de repos deviennent beaucoup plus confortables.</p>${crewLines||'<div class="empty-state"><span>Crée une ligne pour voir les besoins d’équipage.</span></div>'}<h3>Personnel recruté (${staff.items.length})</h3><div>${staff.items.length?staff.items.map(e=>`<div class="staff-card"><div><b>${e.name}</b><span>${e.role_label}${e.qualification?' · '+e.qualification:''} · base ${e.home_hub||'mobile'} · ${money(e.salary_monthly)}/mois</span></div><button class="mini-btn danger-btn" data-fire="${e.id}">Licencier</button></div>`).join(''):'<div class="empty-state"><span>Aucun salarié recruté.</span></div>'}</div></section><section class="panel"><h2>Recrutement</h2><p class="muted">Le personnel recruté est basé sur le hub actif puis utilisé automatiquement par le moteur OPS.</p><div id="candidateList">${cands.items.filter(c=>['pilot','copilot','cabin_crew','mechanic','ground_agent'].includes(c.role)).slice(0,24).map(c=>`<div class="staff-card"><div><b>${c.name}</b><span>${c.role_label}${c.qualification?' · '+c.qualification:''} · qualité ${c.quality}% · ${money(c.salary_monthly)}/mois</span></div><button class="mini-btn" data-hire="${c.id}">Recruter · ${money(c.hiring_fee)}</button></div>`).join('')}</div></section></div>`;
  root.querySelectorAll('[data-fire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/'+b.dataset.fire,{method:'DELETE'});toast('Employé libéré');await loadState();renderStaff(root)}catch(e){toast(e.message)}}));
  root.querySelectorAll('[data-hire]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/staff/hire',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({candidate_id:b.dataset.hire,home_hub:activeHubIdent||(STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident||''})});toast('Recrutement effectué · affectation automatique active');await loadState();renderStaff(root)}catch(e){toast(e.message)}}));
}

async function renderFinance(root){
  const [d,banks]=await Promise.all([api('/api/finance'),api('/api/banks?ident='+encodeURIComponent((STATE.hubs.find(h=>h.is_primary)||STATE.hubs[0])?.ident||''))]);
  const allLoans=[...(d.bank_loans||[]),...(d.loans||[])],debt=allLoans.reduce((s,x)=>s+x.outstanding,0);
  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Finance</h2><div class="estimate-grid"><div><small>Trésorerie</small><b>${money(d.cash)}</b></div><div><small>Masse salariale</small><b>${money(d.monthly_payroll)}/mois</b></div><div><small>Dette</small><b>${money(debt)}</b></div><div><small>Dernier vol</small><b>${d.flights[0]?money(d.flights[0].profit):'—'}</b></div></div><h3>Résultat par vol</h3><div class="table-scroll"><table class="finance-table"><thead><tr><th>Vol</th><th>Pax</th><th>Recettes</th><th>Coûts</th><th>Profit</th></tr></thead><tbody>${d.flights.slice(0,30).map(f=>`<tr><td>${f.tail} · ${f.origin}→${f.destination}</td><td>${f.passengers} · ${Math.round(f.load_factor*100)}%</td><td>${money(f.ticket_revenue+f.ancillary_revenue)}</td><td>${money(f.operating_cost)}</td><td class="${f.profit>=0?'profit-pos':'profit-neg'}">${money(f.profit)}</td></tr>`).join('')}</tbody></table></div></section><section class="panel"><h2>Banques · ${banks.hub||banks.country}</h2><p class="muted">Les offres changent selon le pays de ton hub principal et ton niveau joueur.</p><div class="bank-offers">${banks.offers.map((b,i)=>`<button class="bank-offer ${i===0?'selected':''}" data-bank="${b.id}" ${b.available?'':'disabled'}><b>${b.name}</b><span>à partir de ${(b.base_apr*100).toFixed(2)}% · plafond ${money(b.max_amount)}</span><small>${b.available?b.advantage:'Niveau '+b.min_level+' requis'}</small></button>`).join('')}</div><input type="hidden" id="selectedBank" value="${banks.offers.find(x=>x.available)?.id||''}"><label>Montant<input id="loanAmount" type="number" value="25000000" min="1000000"></label><label>Durée<select id="loanTerm"><option>12</option><option>24</option><option selected>36</option><option>60</option><option>84</option><option>120</option></select></label><button class="primary" id="takeBankLoan" ${banks.offers.some(x=>x.available)?'':'disabled'}>Demander le financement</button><h3>Emprunts en cours</h3>${allLoans.map(l=>`<div class="manage-card"><b>${l.bank_name||'Banque'}</b><p>${money(l.outstanding)} · ${(l.apr*100).toFixed(2)}% · ${l.term_months} mois</p>${l.legacy?'':`<button class="mini-btn" data-bankrepay="${l.id}" data-out="${l.outstanding}">Rembourser 10%</button>`}</div>`).join('')||'<p class="muted">Aucun emprunt.</p>'}</section></div>`;
  const offerBtns=root.querySelectorAll('[data-bank]');offerBtns.forEach(btn=>btn.addEventListener('click',()=>{offerBtns.forEach(x=>x.classList.remove('selected'));btn.classList.add('selected');$('#selectedBank').value=btn.dataset.bank}));
  $('#takeBankLoan')?.addEventListener('click',async()=>{try{await api('/api/finance/bank-loan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({amount:Number($('#loanAmount').value),term_months:Number($('#loanTerm').value),bank_id:$('#selectedBank').value})});toast('Financement accordé');await loadState();renderFinance(root)}catch(e){toast(e.message)}});
  root.querySelectorAll('[data-bankrepay]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/finance/bank-loan/'+b.dataset.bankrepay+'/repay',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({loan_id:Number(b.dataset.bankrepay),amount:Number(b.dataset.out)*.1})});toast('Remboursement effectué');await loadState();renderFinance(root)}catch(e){toast(e.message)}}));
}

async function renderHotels(root){
  const d=await api('/api/hotels');const canBuild=d.player_level>=20;
  root.innerHTML=`<div class="management-grid"><section class="panel"><h2>Partenaires hôteliers réels par marché</h2><p class="muted">Les marques proposées dépendent du pays et du profil réel du hub. Aucun grand hôtel n’apparaît automatiquement dans un petit aéroport.</p>${(d.partner_offers||[]).map(o=>`<div class="manage-card"><h3>${o.name} · ${o.airport_code}</h3><p>${o.character} · satisfaction ${o.hub_satisfaction}%</p><button class="${o.available?'primary':'secondary'}" data-hotelpartner="${o.key}" ${o.available?'':'disabled'}>${o.available?'Signer · '+money(o.partnership_fee):'Niveau '+o.min_level+' + satisfaction 65%'}</button></div>`).join('')||'<p class="muted">Aucune offre disponible.</p>'}</section><section class="panel"><h2>Immobilier hôtelier du groupe</h2>${d.items.map(h=>`<div class="manage-card"><h3>${h.name}</h3><p>${h.airport_ident} · ${h.stars}★ · ${h.rooms} chambres · niv. ${h.level}/10</p><button class="mini-btn" data-hotelup="${h.id}">Agrandir</button></div>`).join('')||'<p class="muted">Aucun hôtel détenu.</p>'}<hr><h3>Construire votre propre hôtel</h3><p class="muted">Déblocage tardif : niveau joueur 20 et satisfaction hub ≥ 70%.</p><label>Hub<select id="hotelHub" ${canBuild?'':'disabled'}>${STATE.hubs.map(h=>`<option value="${h.ident}">${h.airport.code} · ${h.airport.name}</option>`).join('')}</select></label><label>Nom<input id="hotelName" value="${STATE.profile.logo_text} Hotel" ${canBuild?'':'disabled'}></label><label>Étoiles<select id="hotelStars" ${canBuild?'':'disabled'}><option>2</option><option selected>3</option><option>4</option><option>5</option></select></label><label>Chambres<input id="hotelRooms" type="number" value="120" min="60" max="900" ${canBuild?'':'disabled'}></label><button class="primary" id="buildHotel" ${canBuild?'':'disabled'}>${canBuild?'Construire':'Niveau 20 requis'}</button></section></div>`;
  root.querySelectorAll('[data-hotelpartner]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/hotels/partner',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({offer_key:b.dataset.hotelpartner})});toast('Partenariat hôtelier signé');await loadState();renderHotels(root)}catch(e){toast(e.message)}}));
  $('#buildHotel')?.addEventListener('click',async()=>{try{await api('/api/hotels',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({airport_ident:$('#hotelHub').value,name:$('#hotelName').value,stars:Number($('#hotelStars').value),rooms:Number($('#hotelRooms').value)})});toast('Hôtel construit');await loadState();renderHotels(root)}catch(e){toast(e.message)}});
  root.querySelectorAll('[data-hotelup]').forEach(b=>b.addEventListener('click',async()=>{try{await api('/api/hotels/upgrade',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({hotel_id:Number(b.dataset.hotelup)})});toast('Hôtel agrandi');await loadState();renderHotels(root)}catch(e){toast(e.message)}}));
}

function loadState(){return api('/api/state').then(d=>{STATE=d;renderHeader();renderHome();renderHubSelector();renderOwnedHubs();renderFleet();renderRoutes();if(worldMap){syncWorldRoutes();syncWorldAircraft()}syncIdentity();updateCockpit();if(document.querySelector('[data-view="management"]')?.classList.contains('active'))renderManagement()}).catch(e=>{if(e.message.includes('connect'))location.href='/login';else toast(e.message)})}

$('#menuBtn')?.addEventListener('click',()=>{$('#moreMenu')?.classList.toggle('open');$('#moreBackdrop')?.classList.toggle('open')});
$('#closeMoreMenu')?.addEventListener('click',()=>{$('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open')});
$('#moreBackdrop')?.addEventListener('click',()=>{$('#moreMenu')?.classList.remove('open');$('#moreBackdrop')?.classList.remove('open')});
$('#toggleRouteForm')?.addEventListener('click',()=>$('#routeForm')?.classList.add('mobile-open'));
$('#closeRouteForm')?.addEventListener('click',()=>$('#routeForm')?.classList.remove('mobile-open'));

// ---------- INITIALISE ----------
loadState().then(()=>loadMarket(true));setInterval(loadState,12000);
if('serviceWorker'in navigator)navigator.serviceWorker.register('/static/sw.js').catch(()=>{});
